package com.fluxcore.fluxcore_erp.api;
import com.fluxcore.fluxcore_erp.domain.Produto; import com.fluxcore.fluxcore_erp.repository.ProdutoRepository; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/produtos") public class ProdutoController {private final ProdutoRepository repo; public ProdutoController(ProdutoRepository r){repo=r;} @GetMapping List<Produto> listar(){return repo.findAllByOrderByNomeAsc();} @PostMapping @ResponseStatus(HttpStatus.CREATED) Produto criar(@Valid @RequestBody Produto x){return repo.save(x);} @PutMapping("/{id}") Produto atualizar(@PathVariable Long id,@Valid @RequestBody Produto x){if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);x.setId(id);return repo.save(x);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void excluir(@PathVariable Long id){if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);repo.deleteById(id);} @GetMapping("/resumo") Map<String,Object> resumo(){var all=repo.findAll(); return Map.of("total",all.size(),"unidades",all.stream().mapToInt(x->x.getQuantidade()==null?0:x.getQuantidade()).sum(),"baixoEstoque",all.stream().filter(x->x.getQuantidade()<=x.getEstoqueMinimo()).count());}}
